import{_ as t,o as l,c as n,j as e,a as r}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第四卷 退潮 · 第78章 花边信","description":"","frontmatter":{},"headers":[],"relativePath":"第78章_花边信.md","filePath":"第78章_花边信.md"}'),o={name:"第78章_花边信.md"};function s(p,a,_,c,d,i){return l(),n("div",null,[...a[0]||(a[0]=[e("h1",{id:"第四卷-退潮-·-第78章-花边信",tabindex:"-1"},[r("第四卷 退潮 · 第78章 花边信 "),e("a",{class:"header-anchor",href:"#第四卷-退潮-·-第78章-花边信","aria-label":'Permalink to "第四卷 退潮 · 第78章 花边信"'},"​")],-1),e("p",null,"深秋的风一进教室就凉了半截，我把窗推小一些，回头看见林小满站在后门口朝我招手。 她怀里抱着话剧社的头饰，手心里攥着一封叠得很小的信，信边上画了一圈细细的花。 “江苒让我带给你的。”她压低声音说，“你先看，看完再决定要不要去找她。” 我把信接过来，纸带着一点潮气，摸上去软软的，还留着她指尖的凉，纸边花纹蹭着指腹有点痒。 陈默从前面探过头，笑嘻嘻地问：“又是秘密情报？纸上有花边，我都看见了。” 我说：“算是吧，你先背你的词。” 他吐了吐舌头，转回去跟顾远对词，声音压得很低。",-1),e("p",null,"我把信展开，里面是她的字，细细瘦瘦，四边都描了小花边，藤蔓一样绕着。 开头她写，深秋的教室好冷，排练室更冷，窗户关不上，风一直灌进来。 我看着看着，心就跟着紧了一下。 她说最近话剧社出了风波，原本定好她演那个爱笑的姑娘，不知怎么换了人。 有人在走廊里说她靠老师才拿到角色，说得很难听。 何晓当时也在场，气得脸都红了，想上去理论，被她拉住了。 她写，我不想吵，我一吵，这事就更大了。 那天排练结束后，带社团的老师把她留下来，轻轻拉住了她的手腕。 老师的手很暖，指尖有一点粉笔灰的粗糙，落在她冰凉的皮肤上，像捂着一块小小的炭。 老师说，别把那些话放在心上，角色的事我会再去问问，你先好好上课。 她写到这里，字有点洇开，像是笔停了很久。 她说，老师拉住我的那一下，我忽然很想哭，又觉得不能哭。 排练室的灯很白，照在地板上，照出两个长长的影子。 窗外有落叶贴在玻璃上，又滑下去，发出很细的声音。",-1),e("p",null,"我把信翻过来，背面画了一杯热水，旁边写着，想喝热水了。 她说宋阿婆上次塞的两颗糖，她留了一颗在书包夹层里，烦了就拿出来含着，甜一点，心里就稳一些。 她还说在旧书里找到那张叶脉卡片，夹在信里给我，让我帮她收着，免得她弄丢。 我摸了摸信封，果然摸到一片薄薄的硬，抽出来看，正是那张卡片，边缘已经被磨得发亮。 林小满在一旁小声问：“她还好吗？” 我说：“信上说还好，可我觉得她藏了事。” 林小满叹气，在我旁边坐下来，把头饰放在膝盖上。 “你不知道，那天走廊围了好多人。”她说，“何晓都快哭了，江苒还笑着说没关系。” 我说：“她越是难受，越是笑。” 陈默忍不住回头：“江苒被说了？她在哪儿，我去帮她说回来。” 顾远拉住他：“你别添乱，人家要的是安静。” 陈默撇嘴：“被人说了还不还嘴，多憋屈。” 我说：“她有她的想法，我们先稳住。”",-1),e("p",null,"信的第二页，字小了许多，像写得很晚。 她写，昨晚写完作业，很想给我打个电话，手机拿起来，又放下了。 她说怕打扰我晚自习，又怕我听见她的声音会担心。 她写，我在阳台站了一会儿，风吹得衣角一直飘，路灯黄黄的，有只猫从墙根走过去，尾巴翘得高高的。 我想跟你说说话，又想让你好好睡觉，最后只好都写在这封花边信里了。 看到这里，我手指顿了一下，纸角被我捏得起了皱。 晚自习的教室里，粉笔灰浮在光里，脚底有点凉。 我抬头看黑板，老周刚走进来，抱着一摞本子，目光扫了一圈。 他看见我手里的信，脚步停了一下，没有走过来，只轻轻点头。 我赶紧把信折好塞进课桌，心跳有些快。 老周在讲台上说，天气凉了，多穿点，话剧社的事，学校会处理。 他说这话时，眼神往我这边飘了一下，又很快移开。 林小满用胳膊碰碰我：“看吧，老师们都知道了。” 我说：“知道了也好，总会有人管。” 她小声说：“江苒怕你分心，才让我别声张，只给你一个人看。”",-1),e("p",null,"下课后，我拿着信去走廊尽头，那里风大，能闻到食堂飘来的饭香。 陈默追出来，递给我一杯热水：“别皱眉了，喝点。” 我接过杯子喝了一口，暖意顺着喉咙下去，想起她信里写的那杯热水。 我说：“她排练室冷，我想把外套给她送去。” 陈默说：“送啊，还用问？她会不会不好意思？” 顾远靠在栏杆上说：“她心里惦记你，怕你听了跟着睡不好。” 这话说得我心里酸了一下。 走廊里有人抱着画板跑过，带起一阵风，把我衣领吹得翻起来。 我摸出手机，她的号码躺在第一个，名字后面跟着一颗小星星。 我想打过去，问问她手腕还凉不凉，问问角色到底怎么回事，可手指停在按键上，又想起她那句怕打扰。 林小满说：“要不你先回信？她看见你的字，也会安心。” 我说：“回信太慢，我想晚上去排练室门口等她。” 陈默拍手：“这才对，见一面比什么都强。” 顾远想了想，低声说：“别在门口堵着，去小路那棵树下等，她排练完会经过那里。” 我点点头，把信叠好放进口袋，卡片硌着手心，凉凉的，却让人踏实。",-1),e("p",null,"回到座位我把抽屉里的信纸抽出来，先把桌面的书本往两边推开，纸铺平后用手掌一点点抹开。笔帽有点松，我拧紧了才落笔，笔尖划过纸面有细细的涩，墨迹很快渗开。我想先写一句别硬撑，写了又划掉，改成排练室冷的话就把外套穿上，字写得慢，怕写重了洇开。陈默探头小声说你倒是快写啊，我说急什么，写给她的字不能毛躁。纸角翘起，我用橡皮压住，写了半页停下来，抬头看窗外，心里那点闷被笔尖的沙沙声一点点带走。那会儿想起她秋天在阳台站着看猫的样子，想起她总把想说的话折进花边里，心里软得有点酸。",-1),e("p",null,"最后一节课，我有些坐不住，眼睛总往窗外看。 云压得很低，风把树叶吹得哗哗响，有几片落在窗台上，又被吹走。 我把信又看了一遍，看到末尾那行小字。 她写，如果你看到这里还愿意来见我，今晚排练结束后，我在老地方等你一会儿，就一会儿。 我的心一下提起来，老地方，是小路那棵树下吗。 下课铃一响，我立刻站起来，把书包甩上肩。 林小满冲我眨眼：“快去吧，别让她等太久。” 陈默在后面喊：“带杯热水去，她肯定没吃晚饭。” 我抓起保温杯塞进口袋，跟着人流往外走。 风从楼道口灌进来，吹得眼睛发涩，口袋里的信纸沙沙响。 我一边走一边想，她今晚穿那件薄外套了吗，窗户修好了吗。 走到小路拐角时，天已暗下来，路灯一盏盏亮起来。 远远的，我看见那棵树下站着一个人，影子被拉得很长。 我加快脚步，心快要撞出来，可走近了，才发现树下站着的是何晓。 她手里捏着另一封花边信，边角画着同样的藤蔓，抬头看见我，脸色一下变了。 她说：“你也来找她？你知道她去哪儿了吗，排练刚结束她就不见了。”",-1)])])}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
